'use strict';
const FREE_DEMO='https://dimora-esperienza-demo.vincenzo-b.chatgpt.site';
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const DOCS=[{id:'plan',name:'Planimetria della casa',source:'Proprietario · raccolta del fascicolo',version:1},{id:'book',name:'Libretto caldaia',source:'Tecnico · raccolta del fascicolo',version:1}];
function initialState(){return {step:0,reached:0,done:[],received:false,selection:['plan','book'],asset:true,email:'nuovo.proprietario@example.test',giftRights:false,acceptGift:false,unitRights:false,publishRights:false,manifest:null,giftStatus:'Da preparare',homeDocs:[],homeObjects:[],unitInvite:false,linked:false,commonSelected:true,proposal:true,published:null,reminderChoice:'Aggiungi alle mie attività',reminderDate:'2026-12-01',tasks:[],issueTitle:'Luce dell’ingresso spenta',issueText:'L’illuminazione della Scala A non si accende. Esempio dimostrativo.',issue:null,replyStatus:'Intervento programmato',replyText:'Il tecnico è previsto domani. Esempio dimostrativo.',events:[],error:''};}
let G=initialState();
const STEPS=[
 {role:'intro',who:'Una casa. Tre prospettive.',chapter:0,title:'La storia di una casa, insieme.',lead:'Segui un solo percorso: dall’agenzia alla tua Home, fino agli aggiornamenti dell’amministratore. Il profilo cambia al momento giusto.',benefit:'Capisci cosa offre Dimora provando i passaggi, senza cercare nei menu.',transfer:['Agenzia','Home','Amministratore'],help:'Una storia di esempio in 12 passaggi, circa 4–6 minuti. Nessuna registrazione nella demo, nessun dato personale da caricare.',cta:'Inizia il percorso →'},
 {role:'agency',who:'Agenzia Aurora · Agenzia',chapter:0,title:'Un fascicolo, per sapere cosa serve.',lead:'La casa è in vendita. La planimetria è già nel fascicolo; arriva anche il libretto della caldaia. Rivedilo prima di usarlo.',benefit:'Documenti e informazioni hanno un posto e una provenienza chiari.',transfer:['Proprietario e tecnico','Agenzia'],help:'La revisione di questo esempio non certifica correttezza tecnica o conformità.',cta:'Ricevi e conferma la revisione demo →'},
 {role:'agency',who:'Agenzia Aurora · Agenzia',chapter:0,title:'Scegli la memoria da consegnare.',lead:'Prepara la Home Gift: seleziona i documenti utili al nuovo proprietario e, se vuoi, anche la scheda della caldaia.',benefit:'Il valore del fascicolo accompagna la casa anche dopo la consegna delle chiavi.',transfer:['Fascicolo','Home Gift'],help:'La scheda caldaia richiede il suo libretto. I documenti personali del venditore restano esclusi.',cta:'Prepara la selezione →'},
 {role:'agency',who:'Agenzia Aurora · Agenzia',chapter:0,title:'La consegna è una scelta precisa.',lead:'Controlla il manifesto: chi riceve cosa, con quali fonti e versioni. Solo dopo predisponi l’invito dimostrativo.',benefit:'È chiaro cosa viene consegnato e cosa resta fuori.',transfer:['Agenzia','Invito Home Gift'],help:'Non viene inviata un’email né creato un account. Il prossimo passo cambia automaticamente prospettiva.',cta:'Predisponi l’invito demo →'},
 {role:'home',who:'Nuovo proprietario · Home',chapter:1,title:'La memoria arriva. Tu decidi.',lead:'Ora sei il nuovo proprietario. L’invito è pronto, ma i documenti non sono ancora nella tua Home: rivedi la consegna e accettala.',benefit:'Mantieni il controllo di ciò che entra nella memoria privata della tua casa.',transfer:['Agenzia','La tua Home'],help:'L’accettazione non concede all’agenzia accesso alla tua Home privata.',cta:'Accetta la consegna nella Home →'},
 {role:'home',who:'Nuovo proprietario · Home',chapter:1,title:'Le chiavi. E le informazioni che servono.',lead:'La selezione è ora nella tua Home. Documenti e schede mantengono la loro fonte: puoi ritrovarli quando devi prenderti cura della casa.',benefit:'Non riparti da zero: la storia utile dell’immobile è già a portata di mano.',transfer:['Home Gift accettata','Memoria della casa'],help:'Garanzie e pagamenti non vengono dedotti. Spese e contatti privati del venditore non sono stati trasferiti.',cta:'Continua con l’Amministratore →'},
 {role:'admin',who:'Studio Verdi · Amministratore',chapter:2,title:'Collega l’unità giusta alla casa.',lead:'Passi allo studio che amministra il condominio. Prepara il collegamento della Scala A, interno 12, alla Home del proprietario.',benefit:'Le informazioni comuni possono raggiungere le persone interessate, con il giusto contesto.',transfer:['Amministratore','Invito per l’unità'],help:'Il collegamento dimostrativo riguarda l’unità. I diritti e la titolarità reali richiederebbero verifiche dedicate.',cta:'Predisponi l’invito per l’unità →'},
 {role:'home',who:'Nuovo proprietario · Home',chapter:2,title:'La tua casa incontra il condominio.',lead:'Torna la prospettiva del proprietario. Accetta il collegamento dell’unità per consultare le informazioni comuni pubblicate dallo studio.',benefit:'Hai una vista comune aggiornata, distinta dai tuoi documenti personali.',transfer:['Invito dello studio','Home collegata'],help:'Lo studio non ottiene accesso a oggetti, spese, contatti o documenti privati della Home.',cta:'Collega la mia unità →'},
 {role:'admin',who:'Studio Verdi · Amministratore',chapter:2,title:'Un aggiornamento, da pubblicare con cura.',lead:'Lo studio dispone del rapporto ascensore. Scegli di pubblicarlo per l’unità collegata e decidi se proporre anche un promemoria al proprietario.',benefit:'Un aggiornamento può essere ritrovato con fonte, versione e destinatari chiari.',transfer:['Memoria tecnica','Informazioni comuni in Home'],help:'Gli appunti interni restano allo studio. Un promemoria personale resta una proposta da confermare in Home.',cta:'Pubblica l’aggiornamento nella demo →'},
 {role:'home',who:'Nuovo proprietario · Home',chapter:2,title:'Sai da dove arriva ogni informazione.',lead:'Nella Home trovi l’aggiornamento dello studio e il rapporto collegato. Se è stato proposto un promemoria, decidi tu se aggiungerlo alle tue attività.',benefit:'La memoria comune ti informa; le scelte sulla tua casa restano tue.',transfer:['Pubblicazione dello studio','Vista comune · eventuale attività'],help:'La data del promemoria è una tua scelta dimostrativa, non una scadenza normativa.',cta:'Decidi il promemoria e continua →'},
 {role:'home',who:'Nuovo proprietario · Home',chapter:3,title:'Anche una richiesta ha il suo contesto.',lead:'Noti che la luce dell’ingresso è spenta. Prepara una segnalazione per lo studio, senza condividere il resto della tua Home.',benefit:'La richiesta arriva con edificio e unità, anziché restare un messaggio senza contesto.',transfer:['Home · Scala A, interno 12','Amministratore'],help:'Il testo è già compilato con un esempio e puoi modificarlo. Nessun messaggio reale verrà inviato.',cta:'Prepara la segnalazione demo →'},
 {role:'admin',who:'Studio Verdi · Amministratore',chapter:3,title:'Una risposta che torna alla casa.',lead:'Lo studio ritrova la segnalazione con il suo contesto. Aggiorna lo stato e prepara una risposta che il proprietario possa consultare.',benefit:'Richiesta e aggiornamento rimangono nello stesso percorso, facili da ritrovare.',transfer:['Amministratore','Home · stato e risposta'],help:'Aggiornamento e intervento sono simulati: non viene contattato alcun tecnico.',cta:'Aggiorna la segnalazione nella demo →'},
 {role:'home',who:'La casa, al centro',chapter:3,title:'Tre prospettive. Una memoria che continua.',lead:'Hai seguito il percorso completo: la memoria consegnata dall’agenzia, gli aggiornamenti comuni dello studio e una richiesta del proprietario con la sua risposta.',benefit:'Dimora mette in relazione le informazioni, lasciando chiara l’origine e il controllo di ciascuna scelta.',transfer:['Agenzia','Home','Amministratore','Home'],help:'Questa è una dimostrazione della visione di prodotto. Nessuna operazione reale è stata eseguita.',cta:'Rivedi dall’inizio →'}
];
function badge(t,kind=''){return `<span class="badge ${kind}">${esc(t)}</span>`;}
function doc(title,sub,status,kind=''){return `<div class="document"><span class="docicon" aria-hidden="true">▤</span><div><strong>${esc(title)}</strong><small>${esc(sub)}</small></div>${status?badge(status,kind):''}</div>`;}
function checkbox(key,label,sub='',disabled=false,checked=null){return `<label class="choice ${disabled?'disabled':''}"><input type="checkbox" data-field="${key}" ${checked===null?(G[key]?'checked':''):(checked?'checked':'')} ${disabled?'disabled':''}><span>${esc(label)}${sub?'<small>'+esc(sub)+'</small>':''}</span></label>`;}
function input(key,label,type='text'){return `<label class="field" for="field-${key}">${esc(label)}<input id="field-${key}" type="${type}" data-field="${key}" value="${esc(G[key])}"></label>`;}
function select(key,label,values){return `<label class="field" for="field-${key}">${esc(label)}<select id="field-${key}" data-field="${key}">${values.map(v=>`<option ${G[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function note(t,kind=''){return `<div class="callout ${kind}">${t}</div>`;}
function house(){return `<div class="house"><svg viewBox="0 0 120 105" role="img" aria-label="Casa dimostrativa"><path d="M18 48 60 15l42 33v48H18Z" fill="#fff" stroke="#a0c5c8" stroke-width="2"/><path d="m10 50 50-40 50 40-8 7-42-32-42 32Z" fill="#366c73"/><path d="M52 96V66h20v30" fill="#8bb5a9"/><rect x="28" y="61" width="15" height="18" fill="#b9dce2"/><path d="M36 61v18M28 70h15" stroke="#fff" stroke-width="2"/></svg><div><strong>Via Roma 12</strong><small>Milano · Scala A · Interno 12<br>Immobile e persone fittizi</small></div></div>`;}
function summaryDocuments(){return (G.manifest?.documents||[]).map(d=>doc(d.name,d.source+' · versione '+d.version,'Selezionato','ok')).join('');}
function panel(){switch(G.step){
case 0:return `${house()}<div class="scene-label">Una storia, senza cambiare menu</div><h2>Segui il prossimo passo.</h2><p>Ogni schermata ti porta dove serve, con una sola azione principale.</p><div class="intro-route"><b>Agenzia</b><span>→</span><b>Home</b><span>→</span><b>Amministratore</b><span>→</span><b>Home</b></div>${note('Provi solo dati di esempio. Il percorso guidato è separato dalla demo a navigazione libera.')}<p class="small">Puoi tornare indietro per rileggere. Le azioni già completate non vengono ripetute.</p>`;
case 1:return `<div class="scene-label">Fascicolo dell’agenzia</div><h2>La raccolta prende forma.</h2><p>Via Roma 12 · Vendita · esempio</p>${doc('Planimetria della casa','Proprietario · versione 1','Presente','ok')}${doc('Libretto caldaia','Tecnico · versione 1',G.received?'Esaminato':'Da ricevere',G.received?'ok':'pending')}${note('Con il pulsante qui sotto simuli la ricezione e confermi di aver esaminato il documento. Il dato resta collegato alla fonte.')}<p class="small">È una revisione dimostrativa, non una certificazione dell’immobile.</p>`;
case 2:return `<div class="scene-label">Home Gift · selezione</div><h2>Porta solo ciò che serve.</h2>${DOCS.map(d=>`<label class="choice"><input type="checkbox" data-doc="${d.id}" ${G.selection.includes(d.id)?'checked':''}><span>${esc(d.name)}<small>${esc(d.source)} · v${d.version}</small></span></label>`).join('')}${checkbox('asset','Includi la scheda della caldaia','Collegata al libretto selezionato. Garanzia da verificare.')}${checkbox('personal','Documento personale del venditore','Escluso: non entra nella Home Gift.',true,false)}${note('Nessuna spesa o contatto privato del venditore viene incluso.')}<p class="small">Se togli il libretto, togli anche la scheda collegata oppure riseleziona la sua fonte.</p>`;
case 3:return `<div class="scene-label">Manifesto di consegna</div><h2>Una selezione trasparente.</h2>${summaryDocuments()}${G.manifest?.asset?doc('Caldaia della casa','Scheda · fonte: libretto caldaia','Inclusa','ok'):''}${input('email','Destinatario dimostrativo','email')}${checkbox('giftRights','Ho controllato destinatario, selezione e diritti nella demo.')}${note('Il manifesto conserverà queste versioni. Il destinatario deve accettare la consegna.')}`;
case 4:return `<div class="scene-label">Home · consegna ricevuta</div><h2>Agenzia Aurora ti consegna la memoria.</h2><p>Per ${esc(G.manifest?.email)} · ${badge(G.giftStatus,'pending')}</p>${summaryDocuments()}${G.manifest?.asset?doc('Caldaia della casa','Scheda collegata al libretto','Da accettare','pending'):''}${checkbox('acceptGift','Ho esaminato la consegna per la mia casa nella demo.')}${note('Prima della tua accettazione, la nuova Home di questo percorso è ancora vuota.')}`;
case 5:return `<div class="scene-label">Home · memoria personale</div><h2>La tua casa ha un punto di partenza.</h2><div class="factgrid"><div class="fact"><span>Documenti ricevuti</span><strong>${G.homeDocs.length}</strong><span>Da Home Gift · Agenzia Aurora</span></div><div class="fact"><span>Schede collegate</span><strong>${G.homeObjects.length}</strong><span>Con fonte inclusa</span></div></div>${G.homeDocs.map(d=>doc(d.name,'Da Agenzia Aurora · origine '+d.source+' · v'+d.version,'Nella Home','ok')).join('')}${G.homeObjects.map(o=>doc(o.name,'Fonte: libretto · garanzia '+o.warranty,'Collegata','ok')).join('')}${note('L’agenzia non vede i documenti privati che aggiungerai in seguito.','success')}`;
case 6:return `<div class="scene-label">Amministratore · unità</div><h2>Condominio Roma</h2>${house()}${doc('Scala A · Interno 12','Destinatario: '+G.manifest?.email,'Da collegare','pending')}${checkbox('unitRights','Ho controllato unità, destinatario e diritti nella demo.')}${note('L’invito riguarda questa unità e la vista comune, non l’accesso alla Home privata.')}`;
case 7:return `<div class="scene-label">Home · invito dello studio</div><h2>Studio Verdi ti invita a collegare l’unità.</h2>${doc('Condominio Roma','Scala A · Interno 12','Invito pronto','pending')}<p>Accettando nella demo potrai consultare ciò che lo studio pubblica per la tua unità.</p>${note('I documenti della Gift restano nella memoria personale. Il collegamento aggiunge una vista comune distinta.')}<p class="small">Il pulsante qui sotto conferma solo questa scelta dimostrativa.</p>`;
case 8:return `<div class="scene-label">Amministratore · pubblicazione</div><h2>Scegli l’aggiornamento comune.</h2>${checkbox('commonSelected','Rapporto ascensore','Fonte Studio Verdi · documento v1 · destinatario Scala A, interno 12.')}${checkbox('proposal','Proponi anche un promemoria al proprietario','Resta da rivedere in Home: non entra automaticamente nelle attività.')}${checkbox('internal','Appunti interni dello studio','Esclusi dalla pubblicazione.',true,false)}${checkbox('publishRights','Ho controllato contenuti e destinatari della pubblicazione demo.')}${note('Messaggio: «Il rapporto aggiornato è disponibile nella memoria comune». Nessuna modifica ai dati privati della casa.')}`;
case 9:return `<div class="scene-label">Home · condominio</div><h2>Un aggiornamento con la sua origine.</h2>${doc('Rapporto ascensore','Studio Verdi · documento v1 · pubblicazione v1','Vista comune','ok')}<p>Il rapporto è distinto dai ${G.homeDocs.length} documenti personali della Gift.</p>${G.published?.proposal?`${select('reminderChoice','Cosa fare con il promemoria',['Aggiungi alle mie attività','Decidi più avanti'])}${input('reminderDate','Data del mio promemoria','date')}${note('La data resta sotto il tuo controllo. Nessuna scadenza normativa è stata dedotta.')}`:note('Non è stato proposto un promemoria. Le tue attività personali non cambiano.','success')}`;
case 10:return `<div class="scene-label">Home · segnalazione</div><h2>Una richiesta per lo studio.</h2>${input('issueTitle','Problema osservato')}<label class="field" for="field-issueText">Dettagli<textarea id="field-issueText" data-field="issueText">${esc(G.issueText)}</textarea></label>${doc('Scala A · Interno 12','Contesto collegato automaticamente all’esempio','La tua unità','ok')}${note('Vengono predisposti solo il testo della richiesta e il riferimento dell’unità. La memoria privata resta esclusa.')}`;
case 11:return `<div class="scene-label">Amministratore · segnalazione ricevuta</div><h2>${esc(G.issue?.title)}</h2><p>${esc(G.issue?.text)}</p>${badge('Scala A · Interno 12')}${select('replyStatus','Stato della segnalazione',['In valutazione','Intervento programmato','Risolta'])}<label class="field" for="field-replyText">Risposta per il proprietario<textarea id="field-replyText" data-field="replyText">${esc(G.replyText)}</textarea></label>${note('La risposta tornerà alla stessa richiesta nella Home. Nessun professionista viene contattato.')}`;
case 12:return `<div class="scene-label">Home · il percorso completo</div><h2>Le informazioni sono tornate a casa.</h2>${doc(G.issue?.title||'Segnalazione',G.issue?.reply||'',G.issue?.status||'Aggiornata','ok')}<div class="factgrid"><div class="fact"><span>Memoria personale</span><strong>${G.homeDocs.length} documenti</strong><span>Selezionati e accettati</span></div><div class="fact"><span>Memoria comune</span><strong>${G.published?1:0} aggiornamento</strong><span>Fonte e versione distinte</span></div></div>${G.tasks.length?doc(G.tasks[0].title,'Data scelta: '+formatDate(G.tasks[0].date),'Confermato da te','ok'):note('Nessun nuovo promemoria personale: è stata rispettata la tua scelta.')}<div class="scene-label" style="margin-top:25px">La traccia dei passaggi</div>${G.events.filter(e=>e.transfer).map((e,i)=>`<div class="event"><i>${i+1}</i><div><strong>${esc(e.title)}</strong><small>${esc(e.transfer)}</small></div></div>`).join('')}<p style="margin:20px 0 0"><a class="summary-link" href="${FREE_DEMO}" target="_blank" rel="noopener">Esplora anche la demo libera ↗</a></p>`;
}}
function formatDate(d){return d?d.split('-').reverse().join('/'):'Non scelta';}
function log(title,transfer=''){G.events.push({step:G.step,title,transfer});}
function readFields(){document.querySelectorAll('[data-field]').forEach(el=>{G[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;});if(G.step===2)G.selection=[...document.querySelectorAll('[data-doc]:checked')].map(el=>el.dataset.doc);}
function performStep(){if(G.done.includes(G.step))return true;switch(G.step){
case 0:break;
case 1:G.received=true;log('Libretto ricevuto ed esaminato','Tecnico → Agenzia');break;
case 2:if(!G.received){G.error='Rivedi prima il documento del fascicolo.';return false}if(!G.selection.length){G.error='Seleziona almeno un documento da consegnare.';return false}if(G.asset&&!G.selection.includes('book')){G.error='La scheda caldaia richiede il libretto selezionato. Includi il libretto oppure escludi la scheda.';return false}G.manifest={documents:DOCS.filter(d=>G.selection.includes(d.id)).map(d=>({...d})),asset:G.asset,email:'',sender:'Agenzia Aurora',version:1};log('Selezione della memoria preparata');break;
case 3:if(!G.manifest||!/^\S+@\S+\.\S+$/.test(G.email)){G.error='Controlla l’indirizzo del destinatario dimostrativo.';return false}if(!G.giftRights){G.error='Controlla e conferma selezione, destinatario e diritti nella demo.';return false}G.manifest.email=G.email;G.giftStatus='In attesa di accettazione';log('Home Gift predisposta','Agenzia → Home · solo il manifesto selezionato');break;
case 4:if(!G.acceptGift){G.error='Rivedi e conferma la consegna prima di accettarla.';return false}if(G.giftStatus!=='In attesa di accettazione'){G.error='La consegna non è ancora disponibile.';return false}G.homeDocs=G.manifest.documents.map(d=>({...d,origin:'Home Gift · Agenzia Aurora'}));G.homeObjects=G.manifest.asset?[{id:'boiler',name:'Caldaia della casa',source:'book',warranty:'Da verificare'}]:[];G.giftStatus='Accettata';log('Documenti e schede accettati nella Home','Agenzia → Home · copia selezionata, nessun accesso alla memoria privata');break;
case 5:break;
case 6:if(!G.unitRights){G.error='Conferma di aver controllato l’unità e il destinatario della demo.';return false}G.unitInvite=true;log('Invito per Scala A, interno 12','Amministratore → Home · collegamento dell’unità');break;
case 7:if(!G.unitInvite){G.error='L’invito dell’unità non è ancora pronto.';return false}G.linked=true;log('Collegamento dell’unità accettato','Home → Amministratore · solo la vista comune');break;
case 8:if(!G.linked||!G.commonSelected){G.error='Seleziona il rapporto da pubblicare per l’unità collegata.';return false}if(!G.publishRights){G.error='Controlla e conferma contenuti e destinatari nella demo.';return false}G.published={id:'lift-report',title:'Rapporto ascensore',source:'Studio Verdi',documentVersion:1,version:1,unit:'Scala A · Interno 12',proposal:G.proposal};log('Rapporto ascensore pubblicato','Amministratore → Home · fonte e versione nella memoria comune');break;
case 9:if(!G.published){G.error='L’aggiornamento comune non è ancora stato pubblicato.';return false}if(G.published.proposal&&G.reminderChoice==='Aggiungi alle mie attività'){if(!/^\d{4}-\d{2}-\d{2}$/.test(G.reminderDate)){G.error='Scegli una data per il tuo promemoria.';return false}if(!G.tasks.some(t=>t.source===G.published.id))G.tasks.push({id:'reminder',title:'Consulta il rapporto ascensore',date:G.reminderDate,source:G.published.id});log('Promemoria personale confermato','Home · una tua scelta, non un aggiornamento automatico');}break;
case 10:if(!G.linked||!G.issueTitle.trim()||!G.issueText.trim()){G.error='Completa titolo e dettagli della segnalazione dimostrativa.';return false}G.issue={id:'issue-demo',title:G.issueTitle,text:G.issueText,unit:'Scala A · Interno 12',status:'Ricevuta',reply:''};log('Segnalazione predisposta con il contesto','Home → Amministratore · testo e unità, nessun documento privato');break;
case 11:if(!G.issue||!G.replyText.trim()){G.error='Scrivi un aggiornamento per il proprietario.';return false}G.issue.status=G.replyStatus;G.issue.reply=G.replyText;log('Stato e risposta tornano alla casa','Amministratore → Home · stessa richiesta, aggiornamento consultabile');break;
case 12:return true;
}G.done.push(G.step);return true;}
function next(){readFields();G.error='';if(!performStep()){render(false);return}if(G.step===12){goStep(0);return}G.step++;G.reached=Math.max(G.reached,G.step);render(true);}
function goStep(step){readFields();G.step=Math.max(0,Math.min(G.reached,step));G.error='';render(true);}
function primaryLabel(){if(G.step===12)return STEPS[12].cta;if(G.done.includes(G.step))return 'Continua →';if(G.step===9){if(!G.published?.proposal)return 'Continua con una segnalazione →';return G.reminderChoice==='Aggiungi alle mie attività'?'Aggiungi promemoria e continua →':'Continua senza aggiungere promemoria →';}return STEPS[G.step].cta;}
function render(focus=false){const s=STEPS[G.step],done=G.done.includes(G.step);$('#app').innerHTML=`<header class="top"><div class="brand">dimora<span>.</span></div><div class="caption">Un solo percorso.<br>La casa al centro.</div><button data-action="reset">Ricomincia demo</button></header><main class="container"><div class="progress-head"><span>${G.step===0?'La tua visita guidata':G.step===12?'Percorso completato':'Passo '+G.step+' di 12'}</span><span>${['La consegna dell’agenzia','La memoria in Home','La casa e il condominio','La richiesta e la risposta'][s.chapter]}</span></div><div class="track" role="progressbar" aria-label="Avanzamento del percorso" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${G.step}">${[0,1,2,3].map(c=>`<div class="${c===s.chapter?'current':c<s.chapter?'done':''}"></div>`).join('')}</div><div class="stage"><section class="narrative"><div class="role ${s.role}">${s.role==='agency'?'↗':s.role==='home'?'⌂':s.role==='admin'?'▥':'⌂'} ${esc(s.who)}</div><h1 id="step-title" tabindex="-1">${s.title}</h1><p class="lead">${s.lead}</p><div class="benefit"><small>Il beneficio</small><p>${s.benefit}</p></div><div class="transfer" aria-label="Passaggio delle informazioni">${s.transfer.map((v,i)=>(i?'<span aria-hidden="true">→</span>':'')+'<strong>'+esc(v)+'</strong>').join('')}</div><p class="help">${s.help}</p></section><section class="scene" aria-label="Schermata dimostrativa del passo"><div class="scene-head"><strong>${s.role==='agency'?'Agenzia Aurora':s.role==='admin'?'Studio Verdi':s.role==='home'?'Dimora Home':'Via Roma 12'}</strong><span>Dati di esempio</span></div><div class="scene-body">${panel()}</div></section></div>${G.error?'<div class="notice" id="step-error" role="alert">'+esc(G.error)+'</div>':''}<div class="cta-panel"><span class="${done?'completed-label':'step-caption'}">${done?'✓ Passaggio già completato · i dati sono conservati':'Segui il pulsante: il profilo cambia automaticamente.'}</span><div class="buttons"><button class="secondary" data-action="back" ${G.step===0?'disabled':''}>← Indietro</button><button class="primary" data-action="next">${primaryLabel()}</button></div></div>${G.step===12?'<div class="review-nav" aria-label="Rivedi i momenti del percorso">'+[[1,'Agenzia'],[5,'Home Gift accettata'],[8,'Pubblicazione'],[12,'Risultato']].map(([n,t])=>'<button data-action="review" data-step="'+n+'">'+t+'</button>').join('')+'</div>':''}<footer class="footer"><span>Demo guidata parallela · Tutte le operazioni sono simulate.</span><span>Il refresh azzera la sessione. Nessuna email, AI o modifica all’app reale.</span></footer></main>`;if(done)document.querySelectorAll('.scene input,.scene select,.scene textarea').forEach(el=>el.disabled=true);if(G.step===9&&G.reminderChoice==='Decidi più avanti'&&$('#field-reminderDate'))$('#field-reminderDate').disabled=true;if(typeof history!=='undefined')history.replaceState(null,'','#passo-'+G.step);document.title='Dimora · '+(G.step===0?'Percorso guidato':G.step===12?'Il risultato':'Passo '+G.step+' · '+s.who);if(focus){$('#step-title').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;switch(el.dataset.action){case'next':next();break;case'back':goStep(G.step-1);break;case'review':goStep(Number(el.dataset.step));break;case'reset':$('#reset-dialog').showModal();break;case'cancel-reset':$('#reset-dialog').close();break;case'confirm-reset':$('#reset-dialog').close();G=initialState();render(true);break;}});
document.addEventListener('change',e=>{if(e.target.matches('[data-field],[data-doc]')){readFields();if(e.target.dataset.field==='reminderChoice'){const btn=document.querySelector('[data-action="next"]');if(btn)btn.textContent=primaryLabel();if($('#field-reminderDate'))$('#field-reminderDate').disabled=G.reminderChoice==='Decidi più avanti';}}});
window.addEventListener('hashchange',()=>{const m=location.hash.match(/^#passo-(\d+)$/);if(m)goStep(Number(m[1]));});
// A fresh direct link starts at the beginning: later steps require this session's choices.
render();
